from pathlib import Path
from html import escape as e
import math
P=Path('public-safe')
S={
'sco':('California Controller · estate tax','https://www.sco.ca.gov/ardtax_estate_tax.html'),
'prop13':('BOE · property tax overview','https://www.boe.ca.gov/proptaxes/pdf/pub29.pdf'),
'ftb':('FTB · gifts and inheritance','https://www.ftb.ca.gov/file/personal/income-types/gifts-and-inheritance.html'),
'boe':('BOE · Proposition 19','https://boe.ca.gov/prop19/'),
'estate':('IRS · estate tax','https://www.irs.gov/businesses/small-businesses-self-employed/estate-tax'),
'new':('IRS · enacted exclusion','https://www.irs.gov/businesses/small-businesses-self-employed/whats-new-estate-and-gift-tax'),
'basis':('IRS · inherited basis','https://www.irs.gov/faqs/interest-dividends-other-types-of-income/gifts-inheritances/gifts-inheritances'),
'ins':('CDI · residential insurance','https://www.insurance.ca.gov/01-consumers/105-type/5-residential/index.cfm'),
'cpi':('BLS · December 2022 CPI','https://www.bls.gov/news.release/archives/cpi_01122023.htm'),
'court':('California Courts · estate process','https://selfhelp.courts.ca.gov/probate'),
'adjust':('IRS · adjusted basis','https://www.irs.gov/taxtopics/tc703')}
nav=[('index','Overview'),('decision','Decision framework'),('tax','Tax rules'),('costs','Operating costs'),('projections','50-year illustrations'),('stress','Black swans'),('process','Inheritance steps'),('flagged','Flagged for Review'),('sources','Sources & method')]
def link(k):
 a,b=S[k];return f'<a href="{b}">{a}</a>'
def table(head,rows):
 return '<div class="scroll"><table><thead><tr>'+''.join('<th scope="col">'+e(x)+'</th>' for x in head)+ '</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def rows(items):return table(['Topic','Finding / action','Status','Official source'],[(e(a),e(b),e(c),link(d)) for a,b,c,d in items])
def page(name,title,body):
 P.joinpath(name+'.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><title>'+e(title)+' · Inheritance planning</title><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="index.html">◈ Estate decision desk</a><span>PUBLIC • ANONYMIZED</span></header><div class="layout"><nav aria-label="Main">'+''.join(f'<a {"aria-current=page" if name==n else ""} href="{n}.html">{t}</a>' for n,t in nav)+'</nav><main><div class="eyebrow">RESEARCH REVIEW · 11 NOVEMBER 2026</div><h1>'+e(title)+'</h1>'+body+'<footer>Educational analysis, not individualized legal, tax, insurance or investment advice. Recheck rules at transfer. No personal identifiers or owner-supplied financial histories are included in this public artifact.</footer></main></div></body></html>')
page('index','A decision plan, not a prediction','''<p class="lead">One property is expected through a future trust transfer. Another is already owned. Keep those decisions separate.</p><section class="notice"><strong>Privacy comes first.</strong> Property A and Property B are placeholders. Actual valuations, rents, bills, dates of family events, locations and assessment histories are intentionally withheld. Rounding alone cannot prevent identification.</section><div class="cards"><article><h2>Property A</h2><p>Future inherited home. Compare occupancy, rental and sale after checking trust terms and transfer-year law.</p></article><article><h2>Property B</h2><p>Already owned, with existing rental activity and accommodation. No new basis adjustment or reassessment is assumed from inheriting A.</p></article><article><h2>Current decision</h2><p>Preserve flexibility. Do not make an irreversible sale or relocation decision based on a smooth long-run forecast.</p></article></div><h2>Executive summary</h2>'''+rows([
('Working strategy','Use staying in B and selling A after transfer as the comparison baseline, not an established winner. Confirm net proceeds, tax basis and housing preferences first.','Conditional analysis','basis'),
('Live in A','Consider only if genuine principal-residence occupancy is desired and the family-home exclusion qualifies. Savings may be limited by the value cap.','Conditional analysis','boe'),
('Rent A','Require market-supported rent to cover reassessed taxes, vacancy, repairs, insurance, management and tax. No verified rent estimate is available.','Needs review','ins'),
('Estate exposure','Measure the transferor’s entire includible estate and lifetime taxable gifts, not just the beneficiary’s cash inheritance.','Verified rule; private amount withheld','estate'),
('Main limitation','No defensible personalized after-tax ranking exists without verified trust, basis, debt, rental and expense data. This site does not invent them.','Unresolved','adjust')])+ '<p><a class="button" href="decision.html">Explore the decision framework →</a></p>')
page('decision','Compare the incremental decision','<p class="lead">Hold the already-owned property constant unless a separate, fully costed decision changes it. Existing rental income must not disappear simply because occupancy moves.</p>'+rows([
('Occupy A','Net benefit = housing value enjoyed + eligible tax savings − incremental carrying costs − investment opportunity cost. Do not count market rent as cash income from an occupied house.','Framework, not forecast','boe'),
('Rent A','NOI = collected rent − vacancy − management − taxes − insurance − utilities − maintenance − capital reserve. Then subtract debt service and income tax to get spendable cash.','Framework; inputs unverified','adjust'),
('Sell A','Investable proceeds = sale price − selling costs − debt payoff − applicable gain tax − estate settlement allocation. Inherited basis is generally date-of-death FMV, subject to exceptions.','Conditional framework','basis'),
('B treatment','Retain existing leases and costs in all three scenarios. Extra rent from a currently occupied space is not automatic; legality, condition and tenancy terms require review.','User context; not independently verified','court'),
('Comparable endpoints','Compare total after-tax liquidation wealth at the same date, including home selling costs, portfolio tax, cumulative cash flows and equivalent housing consumption.','Analytical method','adjust'),
('Decision gate','Prefer a sale only if its after-tax, risk-adjusted outcome exceeds the alternatives and liquidity/diversification goals support it. Prefer rental only with resilient net cash flow.','Conditional recommendation','basis')])+ '<h2>Illustrative break-even, not a property estimate</h2>'+rows([
('Fictional capital','Assume net sale proceeds $1,000,000 and a 4% net annual alternative return: $40,000 annual opportunity cost.','Assumption / derived; not officially endorsed','basis'),
('Fictional rental hurdle','With $30,000 annual operating costs, $10,000 capital reserve, 5% vacancy and no debt or income tax: break-even scheduled rent = ($40,000 + $30,000 + $10,000) ÷ 0.95 = $84,210/year.','Assumption / derived; pre-income-tax only','adjust'),
('Interpretation','This hurdle excludes appreciation and terminal gain taxes. It is not a sufficient investment ranking and does not establish a rent estimate.','Limitation','adjust')]))
page('tax','Separate three different tax systems',rows([
('Federal estate exclusion','2026 basic exclusion: $15,000,000 per individual. This is not a per-beneficiary allowance. Filing tests include adjusted taxable gifts; deductions affect tax due.','Verified from IRS, retrieved 2026-11-11','new'),
('Headroom','Simplified headroom = applicable exclusion + valid portable exclusion − taxable estate − adjusted taxable gifts. Actual amount: withheld / unverified. No flat penalty is assumed on an inheritance.','Framework only','estate'),
('Trust assets','Trust assets may be included in the gross estate. A trust label alone does not establish estate-tax exemption or inherited basis.','Verified general rule; trust-specific result unknown','estate'),
('Inherited income-tax basis','Generally date-of-death FMV, or elected alternate valuation when applicable. A later sale above adjusted basis may create taxable gain.','Verified general rule, exceptions apply','basis'),
('Already-owned B','Do not reset its income-tax basis merely because A is inherited. Track improvements and allowed/allowable depreciation separately.','Application of basis principles','adjust'),
('California income tax','FTB says not to include the received gift or inheritance in income; subsequent interest, dividends, rental income or sale gains can be taxable. This does not certify a separate estate-tax rule.','Verified general rule','ftb'),
('Prop 13','Base tax is 1% plus voter-approved bonded debt; assessed-value growth is generally limited to no more than 2% except ownership change or new construction. 2% is not a guaranteed annual bill increase.','Verified general rule','prop13'),
('Prop 19 eligibility','Family-home exclusion requires qualifying relationship and principal residence of transferor and transferee. Other investment real estate does not receive this exclusion.','Verified general rule','boe'),
('Prop 19 timing','File homeowners exemption within one year of transfer; exclusion claim within three years or before third-party transfer. Check detailed assessor instructions.','Verified summary','boe'),
('Prop 19 value limit','Current taxable value plus a biennially adjusted statutory allowance limits exclusion. Trust transfer does not automatically preserve the old assessment.','Verified general rule; future allowance unknown','boe'),
('California estate / inheritance tax','Controller states no California estate return for deaths on or after January 1, 2005; inheritance tax collection applies to deaths before June 8, 1982. Do not confuse later income tax with tax on receipt.','Verified current state guidance','sco'),
('Local transfer costs','Local sale/recording/transfer-tax treatment is not certified in this release; no unverified local threshold or sale tax is filled in.','Needs review','prop13'),
('Future laws','The 2040–2050 exclusion, tax brackets and Prop 19 allowance are unknown. Recheck enactments at transfer, not just today’s rules.','Unknown future law','new'),
('Legislation watch','No pending bill is represented here as enacted. An exhaustive current federal/state/local bill search was not completed; historical repo claims are not carried forward as verified.','Needs review','new')]))
page('costs','Budget costs without inventing quotes','<p class="lead">A ZIP-code average is not an insurance quote. Actual values remain blank until supported; source links explain the relevant rule or verification route, not proof of a private bill.</p>'+table(['Cost','A verified annual amount','B verified annual amount','Finding / verification route','Official source'],[
('Insurance','','','Unverified. Obtain occupancy-correct homeowner vs landlord/multiunit terms, replacement-cost valuation, deductibles, liability and loss-of-rent coverage. Do not assume equal premiums.',link('ins')),
('Water / sewer','','','Unverified. Provider, meter, consumption, sewer charges and fixed charges must be established; owner estimates are not public evidence.',link('court')),
('Electricity / solar','','','Unverified. Annual true-up, tariff, export compensation, equipment age and transfer terms are unknown. Do not capitalize a perpetual solar credit.',link('court')),
('Repairs / capital expenditure','','','Unverified. Inspect roof, solar inverter, plumbing, foundation and deferred work; replacement reserves are separate from routine maintenance.',link('ins')),
('Property tax / direct levies','','','Unverified property-specific assessment and tax-rate area. Do not multiply an assumed all-in rate by a possibly land-only assessment.',link('boe')),
('Rental cash flow','','','Unverified. Gross rent is not profit. Verify leases, legal unit count, vacancy, rent regulation and expense allocation privately.',link('adjust'))
])+ '<h2>Insurance research result</h2><p>CDI recommends shopping and comparing policies and provides premium and coverage comparison tools. FAIR Plan coverage is limited; supplemental DIC coverage may be needed. No official source establishes a premium for either specific property. Inventing a replacement estimate would violate the verification requirement.</p>')
# Explicitly fictional and normalized: no owner data used.
def money(x):return '${:,.0f}'.format(math.floor(x/10+0.5)*10)
proj=[]
for y in range(2026,2077):
 n=y-2026; v=1000000*1.03**n; a=200000*1.02**n; inf=1.025**n
 proj.append((str(y),money(v),money(v/inf),money(a),money(a*.01),money(15000*inf),'Illustration only · '+link('boe')+' / '+link('cpi')))
page('projections','50 years: transparent, fictional arithmetic','''<section class="notice"><strong>Not the owner’s forecast.</strong> To avoid exposing private financial fingerprints, this example starts with a fictional $1,000,000 home, $200,000 assessment and $15,000 operating budget. None describes either property. Actual annual valuation, assessment and bills remain unverified and are not filled in.</section><h2>Assumptions and limitations</h2><p>Assume nominal appreciation 3%, general costs/CPI 2.5%, assessment growth 2%, and illustrative base tax 1%. These are analyst-selected sensitivity inputs, not official forecasts or a certified tax bill. Source links provide legal/economic context only. No inheritance reassessment event is applied in this pre-transfer continuity illustration; it must not be used as a post-transfer bill.</p><p>For n = year − 2026: value = $1,000,000 × 1.03ⁿ; real value = value ÷ 1.025ⁿ; assessment = $200,000 × 1.02ⁿ; illustrative base tax = assessment × 1%; operating budget = $15,000 × 1.025ⁿ. Real dollars use 2026 purchasing power. Only display values are rounded to $10; intermediate calculations are not rounded. Tax excludes bonds, direct assessments, exemptions and supplemental bills.</p>'''+table(['Year','Fictional market value','Real value','Continuity assessment','Illustrative base tax','Operating budget','Status / context sources'],proj)+ '<h2>Transfer-year branches</h2>'+rows([
('Rent / no exclusion','Use transfer-date market value as the reassessment planning branch, subject to assessor review. Future private value and bills remain blank.','Framework only','boe'),
('Eligible family home','With old taxable value B, transfer value V and transfer-year allowance L: new taxable value = B + max(0, V − B − L). Confirm assessor treatment and continued eligibility.','Derived from exclusion framework; future inputs unknown','boe'),
('Estate threshold illustration','Assuming, not predicting, 2% annual indexing from the 2026 $15,000,000 exclusion gives '+money(15000000*1.02**14)+' in 2040 and '+money(15000000*1.02**24)+' in 2050. Actual legal indexing and law changes differ.','Hypothetical sensitivity, not future legal allowance','new')]))
page('stress','Black swans & uneven economic paths','<p class="lead">Stress tests are scenarios, not probabilities or historical replays. A smooth baseline hides sequence risk and cash shortages.</p>'+rows([
('Observed inflation','BLS reported CPI-U up 6.5% over the 12 months ending December 2022, with electricity up 14.3%. Broad CPI and utility costs did not move together.','Verified historical context','cpi'),
('Stagflation assumption','Test home growth 0% for five years; costs +7% annually for five years. Fictional $15,000 budget becomes '+money(15000*1.07**5)+'. No probability assigned.','Hypothetical stress; not a BLS forecast','cpi'),
('Housing crash assumption','Apply −30% in year one, then +3% for nine years. Fictional $1,000,000 home ends year ten at '+money(1000000*.7*1.03**9)+', not '+money(1000000*1.03**10)+' under smooth 3% growth.','Hypothetical stress','basis'),
('Portfolio sequence assumption','A fictional $1,000,000 portfolio loses 40%, then earns 6% for nine years: '+money(1000000*.6*1.06**9)+'. No tax, fees or withdrawals; not a return forecast.','Hypothetical stress','adjust'),
('Cash-flow sequence assumption','With $40,000 year-end withdrawals, +20% then −20% leaves $888,000 from $1,000,000; −20% then +20% leaves $872,000. Same two returns, different withdrawal outcome.','Hypothetical arithmetic','adjust'),
('Uninsurable loss / nonrenewal','Test loss of coverage, higher deductibles and uninsured earthquake loss. Generic fire coverage must not be treated as comprehensive catastrophe protection.','Scenario; losses not quantified','ins'),
('Vacancy / repair / law shock','Test one year without rent, a major repair and reduced tax exclusions together. Keep a liquid reserve; its actual size cannot be verified without expenses.','Scenario; private dollar impacts unknown','boe')])+ '<h2>Decision consequence</h2><p>Renting concentrates local housing and tenant risk; selling concentrates timing risk unless proceeds are diversified and liquidity is preserved. Occupying creates a housing benefit, not spendable yield. Re-run all three on the same shock path and liquidation date before selecting a winner.</p>')
page('process','From trust transfer to a decision',rows([
('1 · Before transfer','Privately review deed, trust amendments, successor trustee powers, beneficiaries, debt, ownership shares and inclusion in the transferor’s estate. No document uploads to this site.','Planning checklist, not legal instruction','estate'),
('2 · At death','Identify authorized trustee/executor, obtain records securely, secure property and notify insurer. Determine whether assets pass through trust or require probate.','General checklist','court'),
('3 · Inventory and value','Inventory assets and liabilities; obtain defensible date-of-death valuation and preserve basis documentation.','General checklist','basis'),
('4 · Determine estate filings','Evaluate gross estate, lifetime taxable gifts, deductions, marital provisions and any portability election; tax liability is not just inheritance × a penalty rate.','General checklist','estate'),
('5 · Review property-tax deadlines','Contact assessor promptly about change-in-ownership reporting and supplemental assessment. If genuinely occupying and eligible, meet the one-year homeowners-exemption deadline.','Verified timing; parcel process needs review','boe'),
('6 · Complete exclusion claim','File applicable family-home exclusion within three years or before third-party transfer; confirm residence, relationship and value-limit evidence.','Verified summary; case-specific review needed','boe'),
('7 · Settle and reserve','Authorized fiduciary addresses debts, expenses, taxes and distributions according to governing documents and applicable process. Keep funds for unsettled liabilities.','General checklist','court'),
('8 · Choose and document','Compare verified net sale proceeds to rental NOI and occupancy benefit; confirm policy changes and basis before executing leases, distribution or sale.','Conditional decision gate','adjust'),
('9 · Review annually','Refresh insurance, leases, capital needs, tax bills and continued eligibility; re-evaluate law before the actual future transfer.','Planning recommendation','boe')]))
flags=[
('F01 · Public repository history','Older files include property-specific financial histories. The curated deployment excludes them, but public Git history and prior cached deployments can remain accessible. No guarantee of anonymity is made.','Urgent privacy residual','court'),
('F02 · Unsupported verification claims','Prior scripts check structure and links, not truth of every source assertion. No inherited “verified” status is accepted without source retrieval in this session.','Published for review','court'),
('F03 · Ownership distinction','Prior summary suggests disposing of B as if inherited. B is already owned; A’s transfer does not by itself create a B step-up or reassessment.','Corrected in new analysis','adjust'),
('F04 · Actual financial values','No property-specific assessment, tax, rent, utility, premium or repair amount is officially confirmed. Actual numeric cells remain blank.','Unverified','boe'),
('F05 · Insurance guess','No official property-specific premium supports a generic annual estimate. No premium multiplier is adopted from prior reports.','Unverified','ins'),
('F06 · Trust and basis','Estate inclusion, ownership share, relationship, citizenship/domicile and trust terms are unknown. The ordinary exclusion may not fit nonresident estates.','Unverified','estate'),
('F07 · Assessment discrepancy','A low reported assessment relative to a bill can have multiple explanations. Land-only assessment is a hypothesis, not a verified finding.','Unverified','boe'),
('F08 · State/local and law watch','Attempted FTB estate pages returned 404. State estate/inheritance guidance was subsequently verified with the Controller. Local transfer taxes, rental regulation and pending legislation were not comprehensively reverified. No unsupported amounts are shown.','Needs further official review','new'),
('F09 · No proven optimum','Without official private inputs, an after-tax personalized ranking cannot honestly be certified. The baseline is a decision comparator, not an investment promise.','Unresolved','basis'),
('F10 · Forecasts','The annual table and shock tests are explicitly fictional examples; links do not endorse their chosen growth rates. Actual post-transfer annual forecasts remain unavailable.','Illustration only','cpi')]
page('flagged','Flagged for Review','<p class="lead">These issues do not block publication. They do limit what the analysis can responsibly conclude.</p>'+rows(flags))
page('sources','Sources, evidence & privacy boundaries','<p>Official pages below were retrieved and read during this session on 11 November 2026. This is a targeted verification of the curated release, not certification of every line in the preserved legacy repository. Links in hypothetical rows support context, not their fictional inputs.</p>'+table(['Publisher / topic','Evidence checked','Status'],[(link(k),e({'sco':'California estate-return and historical inheritance-tax dates','prop13':'1% base levy, bonded debt, assessment growth cap and reassessment','ftb':'Inheritance receipt vs subsequent taxable income','boe':'Principal residence, claims timing, value-limit framework','estate':'2026 exclusion, gross estate, lifetime gifts, portability','new':'Public Law 119-21 and 2026 exclusion','basis':'Inherited basis and later sale gains','ins':'Comparison tools; FAIR Plan limitations','cpi':'December 2022 annual CPI and electricity changes','court':'Estate inventory, authority and transfer process','adjust':'Cost basis, improvements and depreciation'}[k]),'Retrieved and read') for k in S])+ '<h2>Verification contract</h2><p>Verified means the stated general rule was checked in retrieved official text, not that a private property figure was verified. Unverified values are blank, not zero. Analysis, assumptions, formulas and stress tests have separate labels. Monetary illustrations are rounded to $10; no external analytics, forms, trackers, libraries or personal-data requests are used.</p><h2>Deployment boundary</h2><p>Only this allowlisted directory is uploaded to Pages. Legacy research trees, data, coordination logs and repository files are excluded. A noindex request is not access control. The public repository and previous commits remain a privacy risk; a private planning tool would be safer for actual financial inputs.</p>')
P.joinpath('style.css').write_text('''*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#182d40;font:16px/1.65 system-ui,sans-serif}header{background:#102b3b;color:#fff;padding:22px 4%;display:flex;justify-content:space-between;align-items:center;gap:20px}header span,.eyebrow{font-size:11px;letter-spacing:1.6px;font-weight:700}.brand{color:white;text-decoration:none;font-weight:750;font-size:20px}.layout{display:grid;grid-template-columns:230px minmax(0,1fr);max-width:1550px;margin:auto}nav{padding:30px 18px}nav a{display:block;padding:11px 16px;text-decoration:none;color:#40596c;border-radius:8px;font-size:14px}nav a:hover,nav a[aria-current]{background:#deecea;color:#006456;font-weight:700}main{padding:38px 40px 70px;min-width:0}h1{font-size:clamp(28px,4vw,44px);letter-spacing:-1.5px;line-height:1.2;margin:14px 0 22px}h2{font-size:21px;margin-top:30px}.eyebrow{color:#08796a}.lead{font-size:19px;max-width:900px;color:#4e6475}.notice{border-left:4px solid #08796a;background:#e7f2ee;padding:22px;border-radius:6px;margin:26px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.cards article{background:white;padding:20px;border:1px solid #dce4ea;border-radius:12px}.cards h2{margin:0}.scroll{overflow:auto;border:1px solid #dce4ea;border-radius:10px;background:#fff;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:14px}th{text-align:left;background:#edf2f5;font-size:12px;text-transform:uppercase;letter-spacing:.5px}th,td{padding:16px;vertical-align:top;border-bottom:1px solid #e5ebef}td:first-child{font-weight:650;min-width:150px}a{color:#006d66;text-underline-offset:3px}td:last-child{min-width:145px}footer{margin-top:45px;border-top:1px solid #dce4ea;padding-top:20px;font-size:12px;color:#536775}.button{display:inline-block;background:#08796a;color:white;border-radius:7px;padding:11px 20px;text-decoration:none}a:focus-visible{outline:3px solid #d77913;outline-offset:3px}@media(max-width:850px){.layout{display:block}nav{display:flex;overflow:auto;padding:12px}nav a{white-space:nowrap}main{padding:22px 18px}.cards{grid-template-columns:1fr}header span{display:none}}''')
